import {HomeIcon, PersonIcon, InboxIcon} from '@primer/octicons-react'
import {useSearchParams} from '@github-ui/use-navigate'
import {NavList} from '@primer/react'
import {sendEvent} from '@github-ui/hydro-analytics'
import styles from './AgentsSidebar.module.css'

export interface AgentsSidebarProps {
  currentUserLogin: string | undefined
}

export type AgentsSidebarView = 'home' | 'created_by_me' | 'needs_attention'

const AGENTS_BASE_PATH = '/copilot/agents'

/**
 * Determines the active sidebar view from current URL search params.
 */
export function getActiveView(searchParams: URLSearchParams, currentUserLogin: string | undefined): AgentsSidebarView {
  const status = searchParams.get('status')
  const author = searchParams.get('author')

  if (status === 'needs_attention') return 'needs_attention'
  if (author === currentUserLogin && currentUserLogin) return 'created_by_me'
  if (author || status) return 'created_by_me' // Any other filter = task list view
  return 'home'
}

/**
 * Sidebar navigation for the /copilot/agents page.
 * Tabs: Home, Created by me, Needs attention.
 * Uses filter-compatible URL params (author, status) instead of a custom view param.
 */
export function AgentsSidebar({currentUserLogin}: AgentsSidebarProps) {
  const [searchParams, setSearchParams] = useSearchParams()

  const activeView = getActiveView(searchParams, currentUserLogin)

  const handleHome = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault()
    sendEvent('agent_sessions.sidebar_tab_click', {target: 'HOME'})
    setSearchParams(new URLSearchParams())
  }

  const handleCreatedByMe = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault()
    sendEvent('agent_sessions.sidebar_tab_click', {target: 'CREATED_BY_ME'})
    const params = new URLSearchParams()
    if (currentUserLogin) params.set('author', currentUserLogin)
    setSearchParams(params)
  }

  const handleNeedsAttention = (e: React.MouseEvent<HTMLAnchorElement>) => {
    e.preventDefault()
    sendEvent('agent_sessions.sidebar_tab_click', {target: 'NEEDS_ATTENTION'})
    const params = new URLSearchParams()
    params.set('status', 'needs_attention')
    setSearchParams(params)
  }

  const createdByMeHref = currentUserLogin
    ? `${AGENTS_BASE_PATH}?author=${encodeURIComponent(currentUserLogin)}`
    : AGENTS_BASE_PATH

  return (
    <div className={styles.sidebarContainer}>
      <NavList aria-label="Agent navigation">
        <NavList.Item
          href={AGENTS_BASE_PATH}
          aria-current={activeView === 'home' ? 'page' : undefined}
          onClick={handleHome}
        >
          <NavList.LeadingVisual>
            <HomeIcon />
          </NavList.LeadingVisual>
          Home
        </NavList.Item>
        {currentUserLogin && (
          <NavList.Item
            href={createdByMeHref}
            aria-current={activeView === 'created_by_me' ? 'page' : undefined}
            onClick={handleCreatedByMe}
          >
            <NavList.LeadingVisual>
              <PersonIcon />
            </NavList.LeadingVisual>
            Created by me
          </NavList.Item>
        )}
        <NavList.Item
          href={`${AGENTS_BASE_PATH}?status=needs_attention`}
          aria-current={activeView === 'needs_attention' ? 'page' : undefined}
          onClick={handleNeedsAttention}
        >
          <NavList.LeadingVisual>
            <InboxIcon />
          </NavList.LeadingVisual>
          Needs attention
        </NavList.Item>
      </NavList>
    </div>
  )
}
